	    booktitle = findControl.Title;
	}

	if (controlId === "" || controlId == null)
	{
	    booktitle += "Chưa có Control.";
	}

	if (!findControl) return;
    
	controluuuid.innerHTML = ` ${booktitle} `;

	document.title = findControl.Title;
}

